class Solution {
public:
    vector<vector<int>> combinationSum3(int k, int n) {
        vector<vector<int>> res;
        vector<int> path;
        auto dfs = [&](auto& self, int start, int remain) -> void {
            if ((int)path.size() == k) {
                if (remain == 0) res.push_back(path);
                return;
            }
            for (int d = start; d <= 9; ++d) {
                if (d > remain) break;
                path.push_back(d);
                self(self, d + 1, remain - d);
                path.pop_back();
            }
        };
        dfs(dfs, 1, n);
        return res;
    }
};

class Solution {
    public List<List<Integer>> combinationSum3(int k, int n) {
        List<List<Integer>> res = new ArrayList<>();
        dfs(1, k, n, new ArrayList<>(), res);
        return res;
    }
    private void dfs(int start, int k, int remain, List<Integer> path, List<List<Integer>> res) {
        if (path.size() == k) {
            if (remain == 0) res.add(new ArrayList<>(path));
            return;
        }
        for (int d = start; d <= 9; d++) {
            if (d > remain) break;
            path.add(d);
            dfs(d + 1, k, remain - d, path, res);
            path.remove(path.size() - 1);
        }
    }
}

var combinationSum3 = function(k, n) {
    const res = [];
    const path = [];
    function backtrack(start, remain) {
        if (path.length === k) {
            if (remain === 0) res.push([...path]);
            return;
        }
        for (let d = start; d <= 9; d++) {
            if (d > remain) break;
            path.push(d);
            backtrack(d + 1, remain - d);
            path.pop();
        }
    }
    backtrack(1, n);
    return res;
};
